u8 PollJoypad() {
    // requires: __location(0xFF00) u8 P1;
    P1 = 0x20;
    u8 dpad = (~P1) & 0x0F;
    P1 = 0x10;
    u8 buttons = ((~P1) & 0x0F) << 4;
    return (u8)(buttons | dpad);
}

